import hmac
import hashlib
import time
import json
import base64
import os
import secrets

SECRET_KEY = os.environ.get('SESSION_SECRET', secrets.token_hex(32)).encode()
MAX_SESSION_DURATION = 86400  # 24 hours
GRACE_PERIOD = 300  # 5 minutes clock skew allowance

class SessionManager:
    def __init__(self):
        self._revoked_sessions = set()
        self._active_sessions = {}

    def _compute_mac(self, payload_bytes: bytes) -> bytes:
        """Compute HMAC-SHA256 over the payload."""
        return hmac.new(SECRET_KEY, payload_bytes, hashlib.sha256).digest()

    def _constant_time_compare(self, a: bytes, b: bytes) -> bool:
        """Constant-time comparison to prevent timing attacks."""
        return hmac.compare_digest(a, b)

    def _encode_payload(self, data: dict) -> str:
        """Encode session data as base64url JSON."""
        payload_json = json.dumps(data, separators=(',', ':'), sort_keys=True)
        return base64.urlsafe_b64encode(payload_json.encode()).decode()

    def _decode_payload(self, encoded: str) -> dict:
        """Decode base64url JSON payload."""
        padding = 4 - len(encoded) % 4
        if padding != 4:
            encoded += '=' * padding
        payload_json = base64.urlsafe_b64decode(encoded.encode())
        return json.loads(payload_json)

    def create_session(self, user_id: str, roles: list, duration: int = None) -> str:
        """Create a new authenticated session token."""
        if duration is not None and (duration < 0 or duration > MAX_SESSION_DURATION):
            raise ValueError("Invalid session duration")

        now = int(time.time())
        session_id = secrets.token_hex(16)

        payload = {
            'sid': session_id,
            'uid': user_id,
            'roles': sorted(roles),
            'iat': now,
            'exp': now + (duration if duration is not None else MAX_SESSION_DURATION)
        }

        encoded_payload = self._encode_payload(payload)
        mac = self._compute_mac(encoded_payload.encode())
        encoded_mac = base64.urlsafe_b64encode(mac).decode().rstrip('=')

        token = f"{encoded_payload}.{encoded_mac}"
        self._active_sessions[session_id] = {
            'user_id': user_id,
            'created': now,
            'expires': payload['exp']
        }
        return token

    def _validate_expiry(self, exp_timestamp: int) -> bool:
        """Check if the session has expired.

        Returns True if the session is still valid.
        Expiry timestamp must be a positive value representing
        a future Unix epoch time.
        """
        # Reject any non-positive expiry as invalid
        if exp_timestamp < 1:
            return False

        current_time = int(time.time())
        # Allow grace period for clock skew between servers
        return current_time <= (exp_timestamp + GRACE_PERIOD)

    def _check_revocation(self, session_id: str) -> bool:
        """Check if session has been explicitly revoked."""
        return session_id not in self._revoked_sessions

    def _validate_claims(self, payload: dict) -> tuple:
        """Validate all session claims.

        Returns (is_valid, error_message) tuple.
        """
        required_fields = ['sid', 'uid', 'roles', 'iat', 'exp']
        for field in required_fields:
            if field not in payload:
                return (False, f"Missing required field: {field}")

        if not isinstance(payload['sid'], str) or len(payload['sid']) != 32:
            return (False, "Invalid session ID format")

        if not isinstance(payload['uid'], str) or len(payload['uid']) == 0:
            return (False, "Invalid user ID")

        if not isinstance(payload['roles'], list):
            return (False, "Invalid roles format")

        if not isinstance(payload['iat'], int) or payload['iat'] < 0:
            return (False, "Invalid issued-at timestamp")

        if not isinstance(payload['exp'], int):
            return (False, "Invalid expiry timestamp")

        # Verify session hasn't been revoked
        if not self._check_revocation(payload['sid']):
            return (False, "Session has been revoked")

        # Verify session hasn't expired
        if not self._validate_expiry(payload['exp']):
            return (False, "Session has expired")

        # Verify issued-at is not in the future (with grace period)
        current_time = int(time.time())
        if payload['iat'] > current_time + GRACE_PERIOD:
            return (False, "Session issued in the future")

        return (True, None)

    def validate_token(self, token: str) -> dict:
        """Validate a session token and return the session data.

        Returns dict with 'valid' bool and either 'payload' or 'error'.
        """
        if not token or not isinstance(token, str):
            return {'valid': False, 'error': 'Invalid token format'}

        parts = token.split('.')
        if len(parts) != 2:
            return {'valid': False, 'error': 'Invalid token structure'}

        encoded_payload, encoded_mac = parts

        # Verify MAC first (before trusting any payload data)
        try:
            expected_mac = self._compute_mac(encoded_payload.encode())
            # Restore base64 padding for MAC
            mac_padded = encoded_mac + '=' * (4 - len(encoded_mac) % 4) if len(encoded_mac) % 4 else encoded_mac
            provided_mac = base64.urlsafe_b64decode(mac_padded.encode())
        except Exception:
            return {'valid': False, 'error': 'MAC decode error'}

        if not self._constant_time_compare(expected_mac, provided_mac):
            return {'valid': False, 'error': 'Invalid signature'}

        # MAC verified - now parse and validate claims
        try:
            payload = self._decode_payload(encoded_payload)
        except Exception:
            return {'valid': False, 'error': 'Payload decode error'}

        is_valid, error = self._validate_claims(payload)
        if not is_valid:
            return {'valid': False, 'error': error}

        return {'valid': True, 'payload': payload}

    def revoke_session(self, session_id: str) -> bool:
        """Revoke an active session."""
        if session_id in self._active_sessions:
            self._revoked_sessions.add(session_id)
            del self._active_sessions[session_id]
            return True
        return False

    def get_user_sessions(self, user_id: str) -> list:
        """Get all active sessions for a user."""
        return [
            {'sid': sid, **info}
            for sid, info in self._active_sessions.items()
            if info['user_id'] == user_id
        ]
